"use client";
import { motion, useScroll, useTransform } from "framer-motion";
import Image from "next/image";
import { useRef } from "react";

export default function About() {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["start start", "end end"],
  });

  // Subtle, classy parallax
  const yHero = useTransform(scrollYProgress, [0, 1], [0, -300]);
  const yImage = useTransform(scrollYProgress, [0, 0.6], [0, -200]);
  const opacityText = useTransform(scrollYProgress, [0.1, 0.3], [0, 1]);

  return (
    <div ref={ref} className="bg-black text-white overflow-hidden">
      {/* HERO – Elegant & cinematic */}
      <section className="relative min-h-screen flex flex-col items-center justify-center px-6">
        <motion.div style={{ y: yHero }} className="relative z-10">
          <div className="relative w-[260px] sm:w-[380px] h-[140px] sm:h-[200px] mx-auto">
            <Image
              src="https://teraawatt.com/teraawattLogo.png"
              alt="Teraawatt"
              fill
              priority
              className="object-contain drop-shadow-2xl"
            />
          </div>

          <motion.h1
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4, duration: 1.2 }}
            className="mt-12 text-center text-6xl sm:text-8xl font-light tracking-tight"
          >
            Powering tomorrow,<br />
            <span className="font-medium text-[#05DF72]">today</span>.
          </motion.h1>

          <motion.p
            style={{ opacity: opacityText }}
            className="mt-8 max-w-2xl mx-auto text-center text-lg sm:text-xl text-gray-400 leading-relaxed"
          >
            A seamless ecosystem of charging, rewards, and lifestyle — built for the electric age.
          </motion.p>

          <motion.button
            whileHover={{ scale: 1.04 }}
            whileTap={{ scale: 0.98 }}
            className="mt-12 px-10 py-4 bg-[#05DF72] text-black font-medium rounded-full text-sm sm:text-base tracking-wider hover:shadow-2xl hover:shadow-[#05DF72]/30 transition-all duration-300"
          >
            Explore the Ecosystem
          </motion.button>
        </motion.div>
      </section>

      {/* Full-bleed image – sophisticated parallax */}
      <motion.div style={{ y: yImage }} className="relative h-screen">
        <Image
          src="https://teraawatt.com/recharge.png"
          alt="Electric future"
          fill
          className="object-cover"
          priority
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
        <div className="absolute bottom-20 left-10 sm:left-20">
          <motion.h2
            initial={{ opacity: 0, x: -60 }}
            whileInView={{ opacity: 1, x: 0 }}
            transition={{ duration: 1.2 }}
            className="text-6xl sm:text-8xl font-light tracking-tight"
          >
            Recharge.<br />
            <span className="text-[#05DF72] font-medium">Reimagine.</span>
          </motion.h2>
        </div>
      </motion.div>

      {/* Text block – calm & confident */}
      <section className="py-32 px-6 max-w-4xl mx-auto text-center">
        <motion.div
          initial={{ opacity: 0, y: 60 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 1 }}
        >
          <p className="text-xl sm:text-2xl text-gray-300 leading-relaxed">
            We’re making electric mobility feel effortless — with intelligent charging,
            rewarding every green mile, and building a world where EVs aren’t just viable.
            They’re inevitable.
          </p>
        </motion.div>
      </section>

      {/* Products – refined cards with subtle depth */}
      <section className="py-24 px-6">
        <div className="max-w-7xl mx-auto grid md:grid-cols-3 gap-12">
          {[
            {
              title: "TeraaCoins",
              desc: "Earn digital currency for sustainable driving and carbon reduction.",
            },
            {
              title: "TeraaVouchers",
              desc: "Prepaid, flexible charging credits with exclusive user perks.",
            },
            {
              title: "TeraaMart",
              desc: "Curated marketplace for premium EV gear and accessories.",
            },
          ].map((item, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 80 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.15, duration: 0.9 }}
              whileHover={{ y: -12 }}
              className="group relative bg-zinc-950/80 backdrop-blur-xl border border-white/10 rounded-3xl p-10 transition-all duration-500"
            >
              <h3 className="text-4xl font-medium mb-6">{item.title}</h3>
              <p className="text-gray-400 leading-relaxed">{item.desc}</p>
              <div className="mt-8 flex items-center gap-3 text-[#05DF72] font-medium opacity-0 group-hover:opacity-100 transition-opacity">
                Discover more <span>→</span>
              </div>
            </motion.div>
          ))}
        </div>
      </section>

      {/* Final CTA – quiet power */}
      <section className="py-40 text-center">
        <motion.h2
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          className="text-6xl sm:text-7xl font-light tracking-tight"
        >
          The future isn’t coming.
        </motion.h2>
        <motion.p
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
          className="mt-6 text-4xl sm:text-5xl text-[#05DF72] font-medium"
        >
          It’s already here.
        </motion.p>

        <motion.button
          whileHover={{ scale: 1.05 }}
          className="mt-16 px-14 py-5 bg-[#05DF72] text-black font-medium rounded-full text-lg tracking-wider hover:shadow-2xl hover:shadow-[#05DF72]/40 transition-all"
        >
          Join the Movement
        </motion.button>
      </section>
    </div>
  );
}